((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"year":1997,"id":"1997-7-8","grades":[7,8],"label":"7–8 классы","tasksUrl":"assets/kenguru/kenguru_1997_class_7-8.pdf","answersUrl":"assets/kenguru/kenguru_1997_answers.pdf","solutionUrl":null,"answerLetters":"ABCDE","cards":[{"number":1,"title":"Тысячи участников","question":"В конкурсе «Кенгуру-96» приняли участие 1 100 000 учащихся из 22 стран. Количество тысяч участников конкурса равно","options":[{"text":"110"},{"text":"1010"},{"text":"100"},{"text":"1100"},{"text":"11 000"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Каждая тысяча — это 1000 участников."},{"title":"Ответ","text":"1 100 000 : 1000 = 1100 тысяч."}]},{"number":2,"title":"Прыжок с трамплина","question":"Я прыгаю с трамплина в воду: сначала трамплин подбрасывает меня вверх на 1 м, затем я лечу вниз на 6 м и, выныривая, поднимаюсь на 2 м до поверхности воды. На какой высоте над водой находится трамплин?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"трамплин находится под водой"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"После полёта вниз я оказался на 2 м ниже поверхности."},{"title":"Ответ","text":"От трамплина до этой точки я опустился на 6 − 1 = 5 м. Значит, трамплин находится на 5 − 2 = 3 м над водой."}]},{"number":3,"title":"Платки Кенгуру","question":"У Кенгуру — насморк. Он пользуется квадратными платками размером 25 × 25 см². За восемь дней Кенгуру израсходовал 3 м² ткани. Сколько платков в день тратил Кенгуру?","options":[{"text":"1"},{"text":"3"},{"text":"6"},{"text":"18"},{"text":"24"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Площадь платка равна 25 × 25 = 625 см². В 3 м² содержится 30 000 см²."},{"title":"Ответ","text":"Всего получилось 30 000 : 625 = 48 платков, то есть 48 : 8 = 6 в день."}]},{"number":4,"title":"Углы треугольника","question":"В треугольнике средний из трех углов вдвое больше самого маленького, а самый большой втрое больше маленького. Этот треугольник","options":[{"text":"равнобедренный"},{"text":"прямоугольный"},{"text":"равносторонний"},{"text":"прямоугольный и равнобедренный"},{"text":"нельзя определить"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Пусть самый маленький угол равен x. Тогда остальные равны 2x и 3x."},{"title":"Ответ","text":"Сумма равна 6x = 180°, поэтому x = 30°, а самый большой угол равен 90°."}]},{"number":5,"title":"Центр симметрии","question":"Какое наименьшее количество клеток нужно дополнительно закрасить в квадрате, чтобы полученная картинка имела центр симметрии?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":{"src":"assets/grades-9-10/1997/task-07.svg","width":208,"height":208,"alt":"Квадрат 4×4. Закрашены первая, третья и четвёртая клетки верхнего ряда, четвёртая клетка третьего ряда и вторая клетка нижнего ряда"},"answer":2,"points":3,"review":[{"title":"Решение","text":"Поверните квадрат мысленно на 180°. Каждая закрашенная клетка без закрашенной пары требует ещё одной клетки."},{"title":"Ответ","text":"Парой верхней третьей клетки уже служит нижняя вторая. Для трёх остальных нужно закрасить по одной клетке."}]},{"number":6,"title":"Цифры на часах","question":"Электронные часы показывают время 19 : 57 : 33. Через какое наименьшее число секунд все цифры на часах изменятся?","options":[{"text":"147 сек."},{"text":"1 сек."},{"text":"27 сек."},{"text":"60 сек."},{"text":"120 сек."}],"condition":null,"answer":0,"points":3,"review":[{"title":"Решение","text":"Первая цифра изменится только при переходе на следующий час. В 20:00:00 все шесть цифр отличаются от цифр в 19:57:33."},{"title":"Ответ","text":"До 19:58:00 остаётся 27 секунд, потом ещё 120 секунд до 20:00:00. Всего 147 секунд."}]},{"number":7,"title":"Ближайшее число","question":"Из данных чисел выберите число, ближайшее к (20 · 0,3 · 1997)/10 000.","options":[{"text":"0,001"},{"text":"0,01"},{"text":"0,1"},{"text":"1"},{"text":"10"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"В числителе 20 × 0,3 = 6, поэтому дробь равна 11 982/10 000 = 1,1982."},{"title":"Ответ","text":"Ближайший из вариантов к 1,1982 — число 1."}]},{"number":8,"title":"Окружность на плёнке","question":"Резиновую пленку растянули в различных направлениях, нарисовали на ней окружность, а затем опустили. Когда пленка приняла первоначальную форму, из нее вырезали круг. Какая из следующих картинок не могла получиться в этом круге?","options":[{"image":"assets/grades-7-8/1997/task-08-answer-1.svg","description":"В круге замкнутая овальная линия"},{"image":"assets/grades-7-8/1997/task-08-answer-2.svg","description":"В круге три раздельные дуги"},{"image":"assets/grades-7-8/1997/task-08-answer-3.svg","description":"В круге одна плавная дуга"},{"image":"assets/grades-7-8/1997/task-08-answer-4.svg","description":"В круге две пересекающиеся волнистые линии"},{"image":"assets/grades-7-8/1997/task-08-answer-5.svg","description":"В круге три непересекающиеся косые линии"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Окружность при изменении формы плёнки остаётся простой замкнутой линией. После обрезки могут сохраниться отдельные дуги."},{"title":"Ответ","text":"На рисунке D две дуги пересекаются внутри круга. При растяжении плёнки такое пересечение появиться не может."}]},{"number":9,"title":"Слова и выражения","question":"Какое из перечисленных слов нельзя употребить ни в одном из следующих выражений: «доказана …»; «возникла …»; «нарисована …»; «принята …»?","options":[{"text":"дилемма"},{"text":"теорема"},{"text":"аксиома"},{"text":"анафема"},{"text":"диаграмма"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Дилемма может возникнуть, теорема — быть доказанной, диаграмма — нарисованной. Аксиому можно принять."},{"title":"Ответ","text":"Для слова «анафема» ни один из четырёх глаголов не подходит."}]},{"number":10,"title":"Дождь над озером","question":"За ночь во время дождя над поверхностью озера выпадает 60 л воды на каждый квадратный метр. Уровень воды в озере при этом поднимается на","options":[{"text":"60 см"},{"text":"6 см"},{"text":"0,6 см"},{"text":"6 м"},{"text":"это зависит от озера"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Распределим выпавшие 60 л воды по квадратному метру. Это 0,06 м³ воды на площади 1 м²."},{"title":"Ответ","text":"Высота слоя равна 0,06 м³ : 1 м² = 0,06 м, то есть 6 см."}]},{"number":11,"title":"Мальчики и девочки","question":"В классе 35 учеников, причем число мальчиков составляет 75 % от числа девочек. Сколько мальчиков в классе?","options":[{"text":"10"},{"text":"15"},{"text":"20"},{"text":"25"},{"text":"30"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"75 % = 3/4, поэтому на три равные доли мальчиков приходятся четыре доли девочек."},{"title":"Ответ","text":"Одна доля равна 35 : 7 = 5, а мальчиков 3 × 5 = 15."}]},{"number":12,"title":"Продолженные грани куба","question":"Если все грани кубика неограниченно продолжить во все стороны, то число частей, на которые будет разбито пространство, равно","options":[{"text":"6"},{"text":"14"},{"text":"18"},{"text":"19"},{"text":"27"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Пара противоположных граней задаёт две параллельные плоскости. В направлении, перпендикулярном к ним, получаются три области."},{"title":"Ответ","text":"Таких независимых направлений три. Всего 3 × 3 × 3 = 27 частей пространства."}]},{"number":13,"title":"Участники в Польше","question":"В Польше в 1996 году в конкурсе «Кенгуру» участвовало 200 000 школьников — на 50 % больше, чем в 1995 году. Если и дальше каждый год число участников будет увеличиваться на 50 %, то в каком году это число превысит 1 000 000?","options":[{"text":"1998"},{"text":"1999"},{"text":"2000"},{"text":"2001"},{"text":"2010"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"После ежегодного роста на 50 % получаются 300 000 в 1997-м, 450 000 в 1998-м и 675 000 в 1999-м."},{"title":"Ответ","text":"Следующее умножение на 1,5 даёт 1 012 500, так что миллион впервые превышен в 2000 году."}]},{"number":14,"title":"Узел на верёвке","question":"Какая веревочка обязательно затянется в узел, если потянуть за концы?","options":[{"image":"assets/separated-choices/1997-5-6/18-1.webp","description":"Верёвочка с высокой петлёй справа сверху","pixelWidth":132,"pixelHeight":157},{"image":"assets/separated-choices/1997-5-6/18-2.webp","description":"Верёвочка с широкой верхней и узкой нижней петлёй","pixelWidth":135,"pixelHeight":128},{"image":"assets/separated-choices/1997-5-6/18-3.webp","description":"Верёвочка с двумя малыми верхними петлями справа","pixelWidth":134,"pixelHeight":156},{"image":"assets/separated-choices/1997-5-6/18-4.webp","description":"Верёвочка с большой петлёй слева и узкой справа","pixelWidth":132,"pixelHeight":170},{"image":"assets/separated-choices/1997-5-6/18-5.webp","description":"Верёвочка с двойной петлёй справа","pixelWidth":141,"pixelHeight":156}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Проследите, как верёвка в каждом пересечении проходит над другим участком или под ним. Попробуйте убрать свободные петли с концов."},{"title":"Ответ","text":"У верёвочки C остаётся простой узел. В остальных рисунках петли можно вытянуть без продевания конца."}]},{"number":15,"title":"Полоски и диагональ","question":"В квадрате, разделенном на четыре равные полоски, проведена диагональ. Чему равна площадь фигуры, закрашенной на рисунке, если сторона квадрата равна 1 м?","options":[{"text":"1/2 м²"},{"text":"2/3 м²"},{"text":"1/4 м²"},{"text":"1/3 м²"},{"text":"3/8 м²"}],"condition":{"src":"assets/grades-7-8/1997/task-15.svg","alt":"Квадрат с диагональю из верхнего левого угла в нижний правый и четырьмя равными горизонтальными полосами. В первой и третьей полосах закрашена часть под диагональю, во второй и четвёртой — над ней.","width":279,"height":276},"answer":4,"points":4,"review":[{"title":"Решение","text":"Две закрашенные части в крайних полосках вместе образуют два треугольника с катетами 1/4 м. Их общая площадь 1/16 м²."},{"title":"Решение","text":"В каждой из двух средних полосок закрашена трапеция с параллельными сторонами 1/2 и 3/4 м и высотой 1/4 м. Обе занимают 5/16 м²."},{"title":"Ответ","text":"Всего закрашено 6/16 = 3/8 м²."}]},{"number":16,"title":"Дроби без пары","question":"Среди пяти данных дробей есть две пары равных. Какая из этих дробей не имеет пары?","options":[{"text":"996/997"},{"text":"199600001996/199700001997"},{"text":"10996/10997"},{"text":"1996/1997"},{"text":"996996/997997"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Числитель и знаменатель дроби B получаются из D умножением на 100 000 001."},{"title":"Ответ","text":"Числитель и знаменатель E получаются из A умножением на 1001. Без пары остаётся C."}]},{"number":17,"title":"Кубики в уголке","question":"Тело, изображенное на рисунке, составлено из кубиков с ребром 1. Если сложить вместе несколько таких тел, то не может получиться куб с размерами","options":[{"text":"2 × 2 × 2"},{"text":"4 × 4 × 4"},{"text":"6 × 6 × 6"},{"text":"8 × 8 × 8"},{"text":"9 × 9 × 9"}],"condition":{"src":"assets/grades-7-8/1997/task-17.svg","alt":"В основании три кубика уголком. Над угловым кубиком стоит четвёртый.","width":210,"height":252},"answer":4,"points":4,"review":[{"title":"Решение","text":"К одному кубику присоединены три соседа в трёх перпендикулярных направлениях, всего четыре кубика. В кубе 2 × 2 × 2 две такие фигуры встают в противоположные углы."},{"title":"Ответ","text":"Поэтому любой куб с чётной стороной можно сложить из таких блоков 2 × 2 × 2. У куба 9 × 9 × 9 число клеток 729, которое на 4 не делится."}]},{"number":18,"title":"Разрезанная пирамида","question":"Правильную пирамиду с квадратом в основании разрезали пополам плоскостью, а потом половинки сложили так, что заштрихованные треугольники совпали. Тело, которое получилось, имеет","options":[{"text":"4 грани"},{"text":"5 граней"},{"text":"6 граней"},{"text":"7 граней"},{"text":"8 граней"}],"condition":{"src":"assets/kenguru/illustrations/1997-pyramid-cut.svg","width":291,"height":300,"alt":"Две половинки пирамиды. На каждой заштрихована одна треугольная грань."},"answer":4,"points":4,"review":[{"title":"Решение","text":"У каждой половинки половина основания, треугольный срез и три части боковых граней. Это пять граней."},{"title":"Ответ","text":"При склейке два заштрихованных треугольника уходят внутрь. Остальные грани не сливаются, их 5 + 5 − 2 = 8."}]},{"number":19,"title":"Остаток от деления","question":"Каков остаток от деления 1997-значного числа 100…0 на 15?","options":[{"text":"1"},{"text":"5"},{"text":"9"},{"text":"10"},{"text":"12"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"10 делится на 15 с остатком 10. Умножение на 10 сохраняет этот остаток, так как 100 = 90 + 10."},{"title":"Ответ","text":"У любой положительной степени десятки, в том числе у 10¹⁹⁹⁶, остаток при делении на 15 равен 10."}]},{"number":20,"title":"Головы марсиан","question":"На Марсе были обнаружены существа, имеющие головы. Один ученый сообщил: «Каждый марсианин имеет две головы». Позднее выяснилось, что он ошибся. Какое из следующих утверждений обязательно верно?","options":[{"text":"Не существует марсиан с двумя головами."},{"text":"Каждый марсианин имеет или одну голову, или больше двух."},{"text":"Существует марсианин с одной головой."},{"text":"Существует марсианин, имеющий больше двух голов."},{"text":"Существует марсианин, имеющий или одну голову, или больше двух."}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Если утверждение про всех марсиан ложно, хотя бы у одного марсианина число голов не равно двум."},{"title":"Ответ","text":"По условию у него есть головы, поэтому у него либо одна голова, либо больше двух."}]},{"number":21,"title":"Угол между отрезками","question":"Прямые a и b параллельны. Найдите угол X.","options":[{"text":"50°"},{"text":"60°"},{"text":"65°"},{"text":"70°"},{"text":"75°"}],"condition":{"src":"assets/grades-7-8/1997/task-21.svg","alt":"Между параллельными прямыми a и b проведена ломаная с углом X в вершине справа. Верхний отрезок образует угол 20° с прямой a, нижний — угол 150° с прямой b.","width":330,"height":210},"answer":0,"points":5,"review":[{"title":"Решение","text":"Проведём через вершину угла X прямую, параллельную a и b. Верхний отрезок образует с ней угол 20°."},{"title":"Ответ","text":"Нижний отрезок образует с этой прямой угол 180° − 150° = 30°. Поэтому X = 20° + 30° = 50°."}]},{"number":22,"title":"Сгибы газетного листа","question":"Газетный лист сложили пополам 5 раз, каждый раз изменяя направление сгиба. Затем отрезали от полученного прямоугольника 4 угла и развернули лист. Сколько в нем дырок?","options":[{"text":"21"},{"text":"25"},{"text":"32"},{"text":"45"},{"text":"60"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Решение","text":"Три сгиба в одном направлении и два в другом делят развёрнутый лист на 8 × 4 прямоугольника."},{"title":"Ответ","text":"Срезы образуют дырки в каждом внутреннем узле сетки. На краю получаются вырезы. Внутренних узлов (8 − 1) × (4 − 1) = 21."}]},{"number":23,"title":"Вершины футбольного мяча","question":"Футбольный мяч представляет собой многогранник с 32 гранями, 20 из которых — белые правильные шестиугольники, а 12 — черные правильные пятиугольники. Сколько вершин у такого многогранника?","options":[{"text":"72"},{"text":"90"},{"text":"60"},{"text":"56"},{"text":"52"}],"condition":{"src":"assets/grades-7-8/1997/task-23.svg","alt":"Футбольный мяч из чёрных пятиугольников и белых шестиугольников.","width":210,"height":207},"answer":2,"points":5,"review":[{"title":"Решение","text":"Всего на гранях 20 × 6 + 12 × 5 = 180 углов. В каждой вершине сходятся как минимум три грани."},{"title":"Решение","text":"Угол правильного пятиугольника равен 108°, шестиугольника — 120°. Четыре таких угла уже дали бы больше 360°, поэтому в вершине ровно три грани."},{"title":"Ответ","text":"Каждая вершина посчитана трижды. Значит, вершин 180 : 3 = 60."}]},{"number":24,"title":"Квадрат из фигурок","question":"Мы можем сложить квадрат, используя четыре из пяти изображенных фигурок. Какая фигурка останется лишней?","options":[{"image":"assets/grades-9-10/1997/task-15-answer-1.svg","description":"Нижний ряд из трёх клеток, верхняя клетка над центром"},{"image":"assets/grades-9-10/1997/task-15-answer-2.svg","description":"Нижний ряд из трёх клеток, две верхние над первыми двумя"},{"image":"assets/grades-9-10/1997/task-15-answer-3.svg","description":"Три ряда по две клетки, верхний ряд сдвинут влево на клетку"},{"image":"assets/grades-9-10/1997/task-15-answer-4.svg","description":"Два нижних ряда по три клетки, верхняя клетка над центром"},{"image":"assets/grades-9-10/1997/task-15-answer-5.svg","description":"Внизу четыре клетки, средний ряд над тремя правыми, вверху крайняя правая"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Фигурки A–E содержат соответственно 4, 5, 6, 7 и 8 единичных клеток. Всего их 30."},{"title":"Ответ","text":"Убрав одну фигурку, получим от 22 до 26 клеток. Из всех этих чисел только 25 является квадратом. Следовательно, надо убрать фигурку B из 5 клеток."}]},{"number":25,"title":"Календарь Буратино","question":"Буратино собрал много календариков за прошлые годы, но у него нет календаря на 1997 год. Календарь какого из прошлых годов он может использовать для правильного определения дней недели?","options":[{"text":"1986"},{"text":"1987"},{"text":"1989"},{"text":"1990"},{"text":"1996"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Решение","text":"Подойдёт невисокосный год, у которого 1 января приходится на тот же день недели, что и в 1997 году."},{"title":"Ответ","text":"От начала 1986 года до начала 1997 прошло 11 лет, в том числе 3 високосных. День недели сдвинулся на 11 + 3 = 14 дней, ровно две недели."}]},{"number":26,"title":"Стрелки между числами","question":"Целые числа от 0 до 200 соединены стрелками, как показано на рисунке. Какой из следующих наборов стрелок ведет от числа 197 к числу 200?","options":[{"image":"assets/grades-7-8/1997/task-26-answer-1.svg","description":"Вправо, вниз, вверх по диагонали"},{"image":"assets/grades-7-8/1997/task-26-answer-2.svg","description":"Вверх по диагонали, вниз, вправо"},{"image":"assets/grades-7-8/1997/task-26-answer-3.svg","description":"Вниз, вправо, вверх"},{"image":"assets/grades-7-8/1997/task-26-answer-4.svg","description":"Вправо, вверх, вправо"},{"image":"assets/grades-7-8/1997/task-26-answer-5.svg","description":"Вверх, вправо, вниз"}],"condition":{"src":"assets/grades-7-8/1997/task-26.svg","alt":"Числа от 0 до 15 соединены по порядку. Стрелки повторяются: вправо, вниз, по диагонали вверх направо, вниз, вправо и вверх.","width":777,"height":186},"answer":4,"points":5,"review":[{"title":"Решение","text":"В каждом блоке из шести шагов стрелки ведут вправо, вниз, по диагонали вверх, вниз, вправо и вверх."},{"title":"Ответ","text":"Число 197 на единицу меньше 198, кратного шести, поэтому следующие три стрелки ведут вверх, вправо и вниз."}]},{"number":27,"title":"Каркас куба","question":"У Пети есть моток жесткой проволоки длиной 12 дм. На какое наименьшее число кусков его надо разрезать, чтобы собрать каркас куба с ребром 1 дм?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"В каждой из восьми вершин сходятся три ребра. Цельный кусок проволоки внутри вершины проходит по двум рёбрам, поэтому в каждой вершине нужен хотя бы один конец. Кусков не меньше четырёх."},{"title":"Ответ","text":"Разделим периметры верхней и нижней граней на два двухрёберных пути каждый. На верхней грани возьмём одну пару противоположных вершин за концы путей, на нижней — другую пару. К каждому пути присоединим по одному вертикальному ребру в разных столбиках."}]},{"number":28,"title":"Квадраты на доске","question":"Клетки доски размером 8 × 8 закрашены так, как показано на рисунке. Сколько квадратов, состоящих из клеток, имеют одинаковое число закрашенных и белых клеток?","options":[{"text":"13"},{"text":"14"},{"text":"28"},{"text":"25"},{"text":"40"}],"condition":{"src":"assets/kenguru/illustrations/1997-eight-cell-board.svg","width":260,"height":260,"alt":"Квадратная сетка 8×8. Верхняя правая и нижняя левая четверти 4×4 закрашены, две остальные белые"},"answer":2,"points":5,"review":[{"title":"Решение","text":"Подходят только квадраты чётной стороны. Пусть центральная горизонтальная граница оставила a строк сверху и b снизу, а центральная вертикальная — c столбцов слева и d справа. Если граница вне квадрата, одна из величин равна нулю."},{"title":"Решение","text":"По рисунку разность между числами клеток двух цветов равна (a − b)(c − d). Для нулевой разности хотя бы одна из двух границ должна делить квадрат ровно пополам."},{"title":"Ответ","text":"Для сторон 2, 4, 6 и 8 число положений соответственно 7 + 7 − 1, 5 + 5 − 1, 3 + 3 − 1 и 1. Вычитаем совпадение для квадрата в центре. Всего 28."}]},{"number":29,"title":"Время в трёх городах","question":"Когда в Москве полдень, в Чикаго 3 часа утра. Когда в Москве 3 часа утра, в Петропавловске-Камчатском полдень. Сколько времени в Чикаго, когда в Петропавловске-Камчатском 3 часа утра?","options":[{"text":"18 час."},{"text":"6 час."},{"text":"9 час."},{"text":"15 час."},{"text":"21 час."}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Петропавловск-Камчатский на 9 часов впереди Москвы, а Чикаго на 9 часов позади Москвы."},{"title":"Ответ","text":"Разница между Петропавловском-Камчатским и Чикаго 18 часов. Значит, в Чикаго 9 утра предыдущего дня."}]},{"number":30,"title":"Скорости на дороге","question":"По дороге, ведущей из леса в поселок, спешат Красная Шапочка и волк, а навстречу им идут бабушка и охотник. Скорость сближения волка и бабушки 18 км/час, Красной Шапочки и бабушки — 8 км/час, а скорость сближения охотника и Красной Шапочки — 12 км/час. С какой скоростью сближаются волк и охотник?","options":[{"text":"26 км/час"},{"text":"22 км/час"},{"text":"18 км/час"},{"text":"14 км/час"},{"text":"16 км/час"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Волк и Красная Шапочка идут в одном направлении. Из скоростей их сближения с бабушкой получаем, что волк быстрее на 18 − 8 = 10 км/ч."},{"title":"Ответ","text":"Охотник сближается с Красной Шапочкой со скоростью 12 км/ч. С волком он сближается на 10 км/ч быстрее, то есть со скоростью 22 км/ч."}]}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

const edition = (globalThis.KENGURU_ARCHIVE["1997-7-8"] ?? [].concat(globalThis.KENGURU_ARCHIVE[1997] ?? []).find(edition => edition.id === "1997-7-8"));
edition.sources.readers = {"tasksUrl":"assets/kenguru/kenguru_1997_class_7-8-reading.pdf"};
register(edition, globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
